
const origin='https://example.com';let revision=1;document.getElementById('pill').onclick=()=>{document.getElementById('site-panel').hidden=false;obUI.focus(document.getElementById('ads'))};for(const id of ['ads','javascript','controller'])document.getElementById(id).onchange=async e=>{const value=e.target.checked;try{await r2.request('site.settings.write',{origin,revision,changes:{[id]:value}},()=>true);revision++;document.getElementById('status').textContent='Saved for example.com in preview.'}catch(err){e.target.checked=!value;r2.toast(err.message)}};document.getElementById('exception').onclick=()=>obUI.openDialog('exception-dialog');document.getElementById('request-review').onclick=async()=>{try{const result=await r2.request('site.consoleException.review',{origin},()=>({allowed:false,code:'NOT_VERIFIED_APP'}));document.getElementById('exception-dialog').close();document.getElementById('status').textContent=result.allowed?'Host approved a verified app exception.':'Kept blocked · this origin is not a verified installed app.';document.getElementById('pill').textContent=result.allowed?'Allowed':'Protected';obUI.focus(document.getElementById('exception'))}catch(e){r2.toast(e.message)}};document.getElementById('clear-data').onclick=()=>obUI.openDialog('clear-dialog');document.getElementById('clear-confirm').onclick=async()=>{try{await r2.request('site.data.clear',{origin,types:['cookies','storage','cache'],confirmed:true},()=>true);document.getElementById('clear-dialog').close();document.getElementById('status').textContent='Site data cleared in preview.';obUI.focus(document.getElementById('clear-data'))}catch(e){r2.toast(e.message)}};